"""Find pairs of images that come from the same source photograph.

Usage:  python main.py [input.zip | input_folder]
Without an argument the script looks, in the current directory and next to
this file, for a zip archive or a folder with images (input*, test*, ...).
Writes output.csv (image_a,image_b) to the current working directory.

Pipeline
  1. SIFT (RootSIFT) keypoints on each image, longest side 640 px.
  2. Candidate pairs: bag-of-visual-words (vocabulary built on the input
     itself, tf-idf, cosine) -> 10 nearest neighbours per image.
  3. Verification of every candidate pair: mutual nearest-neighbour matches
     with ratio test, RANSAC similarity transform (crop / resize / small
     rotation), then photometric agreement of the aligned overlap
     (intensity NCC and Laplacian NCC, so colour edits and blur do not hurt).
  4. A small gradient-boosted tree model (trees embedded in MODEL below,
     fitted on the training pairs) turns the verification features into a
     probability; pairs above the threshold are kept.
  5. Duplicate groups have at most 3 images, so triangles are closed.
  6. If the confident pairs show that duplicates sit next to each other in
     file-name order, that ordering is used as an extra cue (only then).
"""
import csv
import os
import sys
import tempfile
import time
import zipfile
from concurrent.futures import ThreadPoolExecutor

import numpy as np
import cv2

T0 = time.time()
EXTS = (".jpg", ".jpeg", ".png", ".bmp", ".webp", ".tif", ".tiff")
MAX_SIDE = 512
N_FEAT = 400
PHOTO_SIDE = 256
K_NN = 10
THREADS = int(os.environ.get("DUP_THREADS", "0")) or max(1, min(32, (os.cpu_count() or 4)))
cv2.setNumThreads(1)          # parallelism comes from our own thread pool
FEATURES = ["ni", "ratio", "nmr", "lsc", "ang", "err", "ncc", "gncc", "cov"]


def log(*a):
    print(f"[{time.time() - T0:6.1f}s]", *a, flush=True)


# ---------------------------------------------------------------- input
def find_input():
    if len(sys.argv) > 1:
        return sys.argv[1]
    here = os.path.dirname(os.path.abspath(__file__))
    for base in dict.fromkeys([os.getcwd(), here]):
        entries = sorted(os.listdir(base))
        zips = [e for e in entries if e.lower().endswith(".zip")]
        pref = [z for z in zips if any(k in z.lower() for k in ("input", "test"))]
        if pref or zips:
            return os.path.join(base, (pref or zips)[0])
        for name in ("input", "test-input", "test_input", "test", "train-input", "train_input", "train", "images"):
            p = os.path.join(base, name)
            if os.path.isdir(p):
                return p
    raise SystemExit("no input archive or folder found")


def list_images(src):
    """Returns (names, paths). Zip archives are extracted to a temp dir."""
    if os.path.isfile(src) and src.lower().endswith(".zip"):
        tmp = tempfile.mkdtemp(prefix="dups_")
        with zipfile.ZipFile(src) as z:
            z.extractall(tmp)
        src = tmp
    items = []
    for root, _, files in os.walk(src):
        for f in files:
            if f.lower().endswith(EXTS) and not f.startswith("._") and "__MACOSX" not in root:
                items.append((f, os.path.join(root, f)))
    items.sort()
    return [n for n, _ in items], [p for _, p in items]


# ---------------------------------------------------------------- features
def jpeg_size(data):
    """(h, w) from the JPEG SOF marker, or None."""
    b = data.tobytes() if hasattr(data, "tobytes") else data
    if len(b) < 4 or b[0] != 0xFF or b[1] != 0xD8:
        return None
    i = 2
    n = len(b)
    while i + 9 < n:
        if b[i] != 0xFF:
            i += 1
            continue
        m = b[i + 1]
        if m in (0xD8, 0x01) or 0xD0 <= m <= 0xD7 or m == 0xFF:
            i += 1 if m == 0xFF else 2
            continue
        seg = (b[i + 2] << 8) | b[i + 3]
        if m in (0xC0, 0xC1, 0xC2, 0xC3, 0xC5, 0xC6, 0xC7, 0xC9, 0xCA, 0xCB, 0xCD, 0xCE, 0xCF):
            return (b[i + 5] << 8) | b[i + 6], (b[i + 7] << 8) | b[i + 8]
        i += 2 + seg
    return None


REDUCED = [(8, cv2.IMREAD_REDUCED_GRAYSCALE_8), (4, cv2.IMREAD_REDUCED_GRAYSCALE_4), (2, cv2.IMREAD_REDUCED_GRAYSCALE_2)]


def decode_gray(data):
    """Grey image, decoded at reduced size when it is much larger than needed
    (JPEG DCT scaling: far faster and lighter than a full decode)."""
    flag = cv2.IMREAD_GRAYSCALE
    hw = jpeg_size(data)
    if hw is not None:
        for f, fl in REDUCED:
            if max(hw) / f >= MAX_SIDE:
                flag = fl
                break
    im = cv2.imdecode(data, flag)
    if im is None and flag != cv2.IMREAD_GRAYSCALE:
        im = cv2.imdecode(data, cv2.IMREAD_GRAYSCALE)
    return im


def extract(path):
    data = np.fromfile(path, np.uint8)
    im = decode_gray(data)
    del data
    if im is None:
        return None
    h, w = im.shape
    s = MAX_SIDE / max(h, w)
    g = cv2.resize(im, (max(1, round(w * s)), max(1, round(h * s))), interpolation=cv2.INTER_AREA) if s < 1 else im
    sift = cv2.SIFT_create(nfeatures=N_FEAT)
    kp, d = sift.detectAndCompute(g, None)
    if d is None or len(kp) == 0:
        d = np.zeros((0, 128), np.float32)
        pts = np.zeros((0, 2), np.float32)
    else:
        d = d / (d.sum(1, keepdims=True) + 1e-7)
        d = np.sqrt(d).astype(np.float32)
        pts = np.array([k.pt for k in kp], np.float32)
    s2 = PHOTO_SIDE / max(g.shape)
    small = cv2.resize(g, (max(1, round(g.shape[1] * s2)), max(1, round(g.shape[0] * s2))),
                       interpolation=cv2.INTER_AREA) if s2 < 1 else g.copy()
    return pts, d.astype(np.float16), small, s2 if s2 < 1 else 1.0


def all_features(paths):
    with ThreadPoolExecutor(THREADS) as ex:
        res = list(ex.map(extract, paths, chunksize=8))
    out = []
    for r in res:
        if r is None:
            r = (np.zeros((0, 2), np.float32), np.zeros((0, 128), np.float16), np.zeros((8, 8), np.uint8), 1.0)
        out.append(r)
    return out


# ---------------------------------------------------------------- candidates
def bow_candidates(feats, k_nn=K_NN, vocab=768, seed=0):
    n = len(feats)
    D = [f[1] for f in feats]
    own = np.concatenate([np.full(len(d), i) for i, d in enumerate(D)])
    allD = np.concatenate(D)                                  # float16, light
    rng = np.random.default_rng(seed)
    if len(allD) == 0:
        return set()
    vocab = min(vocab, max(8, len(allD) // 20))
    samp = allD[rng.choice(len(allD), min(60000, len(allD)), replace=False)].astype(np.float32)
    C = samp[rng.choice(len(samp), vocab, replace=False)].copy()

    def assign(x):
        out = np.empty(len(x), np.int64)
        cc = 0.5 * (C * C).sum(1)
        for s in range(0, len(x), 8192):
            out[s:s + 8192] = np.argmax(x[s:s + 8192].astype(np.float32) @ C.T - cc, 1)
        return out

    for _ in range(8):
        lab = assign(samp)
        cnt = np.bincount(lab, minlength=vocab)
        acc = np.zeros_like(C)
        np.add.at(acc, lab, samp)
        nz = cnt > 0
        C[nz] = acc[nz] / cnt[nz, None]
    words = assign(allD)
    del allD, samp
    H = np.zeros((n, vocab), np.float32)
    np.add.at(H, (own, words), 1)
    idf = np.log(n / ((H > 0).sum(0) + 1.0))
    X = np.sqrt(H) * idf
    X /= np.linalg.norm(X, axis=1, keepdims=True) + 1e-9
    cand = set()
    kk = min(k_nn, n - 1)
    for s in range(0, n, 512):
        S = X[s:s + 512] @ X.T
        for r in range(S.shape[0]):
            S[r, s + r] = -1
        top = np.argpartition(-S, kk, axis=1)[:, :kk]
        for r in range(S.shape[0]):
            i = s + r
            for j in top[r]:
                j = int(j)
                cand.add((min(i, j), max(i, j)))
    return cand


# ---------------------------------------------------------------- verification
def _ncc(a, b):
    a = a - a.mean()
    b = b - b.mean()
    return float((a * b).sum() / (np.sqrt((a * a).sum() * (b * b).sum()) + 1e-6))


def verify(fa, fb):
    """Feature vector for one pair (see FEATURES)."""
    pa, da, ga, sa = fa
    pb, db, gb, sb = fb
    nm = ni = 0
    sc, ang, err, ncc, gncc, cov = 0.0, 0.0, 5.0, 0.0, 0.0, 0.0
    nmin = min(len(pa), len(pb)) + 1
    if len(da) >= 3 and len(db) >= 3:
        d2 = np.maximum(2 - 2 * (da.astype(np.float32) @ db.astype(np.float32).T), 0)
        nn_ab = np.argmin(d2, 1)
        nn_ba = np.argmin(d2, 0)
        part = np.partition(d2, 1, axis=1)[:, :2]
        ratio = np.sqrt(part[:, 0] / (part[:, 1] + 1e-9))
        ia = np.arange(len(da))
        m = (nn_ba[nn_ab] == ia) & (ratio < 0.85)
        nm = int(m.sum())
        A = pa[ia[m]]
        B = pb[nn_ab[m]]
        if nm >= 4:
            M, inl = cv2.estimateAffinePartial2D(B, A, method=cv2.RANSAC, ransacReprojThreshold=4.0,
                                                 maxIters=2000, confidence=0.995)
            if M is not None:
                inl = inl.ravel().astype(bool)
                ni = int(inl.sum())
                sc = float(np.sqrt(abs(np.linalg.det(M[:, :2]))))
                ang = float(np.degrees(np.arctan2(M[1, 0], M[0, 0])))
                if ni:
                    e = np.linalg.norm(B[inl] @ M[:, :2].T + M[:, 2] - A[inl], axis=1)
                    err = float(e.mean())
                # photometric agreement at PHOTO_SIDE resolution
                Ms = M.copy()
                Ms[:, :2] *= sa / sb
                Ms[:, 2] *= sa
                h, w = ga.shape
                wb = cv2.warpAffine(gb, Ms, (w, h), flags=cv2.INTER_LINEAR, borderValue=0)
                mask = cv2.warpAffine(np.full(gb.shape, 255, np.uint8), Ms, (w, h), flags=cv2.INTER_NEAREST)
                mask = cv2.erode(mask, np.ones((3, 3), np.uint8)) > 0
                cov = float(mask.mean())
                if mask.sum() > 200:
                    fa_ = ga.astype(np.float32)
                    fb_ = wb.astype(np.float32)
                    ncc = _ncc(cv2.GaussianBlur(fa_, (0, 0), 1.0)[mask], cv2.GaussianBlur(fb_, (0, 0), 1.0)[mask])
                    la = cv2.Laplacian(cv2.GaussianBlur(fa_, (0, 0), 0.8), cv2.CV_32F)[mask]
                    lb = cv2.Laplacian(cv2.GaussianBlur(fb_, (0, 0), 0.8), cv2.CV_32F)[mask]
                    gncc = _ncc(la, lb)
    feats = dict(ni=np.log1p(ni), ratio=ni / nmin, nmr=ni / (nm + 1),
                 lsc=abs(np.log(max(sc, 1e-3))) if sc > 0 else 7.0, ang=min(abs(ang), 20.0),
                 err=min(err, 5.0), ncc=ncc, gncc=gncc, cov=cov)
    return [feats[k] for k in FEATURES]


def verify_all(feats, pairs):
    def job(p):
        return verify(feats[p[0]], feats[p[1]])
    with ThreadPoolExecutor(THREADS) as ex:
        return np.array(list(ex.map(job, pairs, chunksize=64)), np.float64).reshape(-1, len(FEATURES))


# ---------------------------------------------------------------- model
MODEL = None  # filled below: {"base": float, "trees": [[(feat, thr, left, right, leaf_value, missing_left), ...], ...]}


def predict_proba(X):
    if MODEL is None:
        # fallback rule (no trees): many consistent inliers + matching structure
        ni = np.expm1(X[:, 0])
        return ((ni >= 8) & (X[:, 7] >= 0.6) & (X[:, 6] >= 0.8)).astype(float)
    raw = np.full(len(X), MODEL["base"])
    for tree in MODEL["trees"]:
        node = np.zeros(len(X), np.int64)
        nodes = np.array(tree, dtype=np.float64)
        for _ in range(64):
            leaf = nodes[node, 4] != 0
            if leaf.all():
                break
            f = nodes[node, 0].astype(np.int64)
            thr = nodes[node, 1]
            go_left = X[np.arange(len(X)), np.maximum(f, 0)] <= thr
            nxt = np.where(go_left, nodes[node, 2], nodes[node, 3]).astype(np.int64)
            node = np.where(leaf, node, nxt)
        raw += nodes[node, 5]
    return 1.0 / (1.0 + np.exp(-raw))


# ---------------------------------------------------------------- decision
THR = 0.5
THR_ADJ = 0.2      # threshold for neighbours in name order (ordered inputs only)
THR_FAR = 0.95     # threshold for non-neighbours (ordered inputs only)


def decide(pairs, prob, n):
    pairs = list(pairs)
    sel = prob >= THR
    gaps = np.array([b - a for a, b in pairs])
    ordered = False
    frac = 0.0
    if sel.sum() >= 20:
        frac = float((gaps[sel] <= 2).mean())
        ordered = frac > 0.5
        log(f"confident pairs {int(sel.sum())}, adjacent in name order {frac:.2f} -> ordered={ordered}")
    if ordered:
        # strongly ordered input: pairs far apart in name order are almost
        # always look-alike copies outside the labelled groups
        thr_far = 1.01 if frac > 0.9 else THR_FAR
        sel = np.where(gaps <= 2, prob >= THR_ADJ, prob >= thr_far)
    keep = {pairs[k]: prob[k] for k in np.where(sel)[0]}
    # close triangles a-b, b-c -> a-c (groups have at most 3 members)
    nb = {}
    for (a, b) in keep:
        nb.setdefault(a, set()).add(b)
        nb.setdefault(b, set()).add(a)
    add = set()
    for a, s in nb.items():
        s = sorted(s)
        if len(s) == 2:
            b, c = s
            if len(nb.get(b, ())) <= 2 and len(nb.get(c, ())) <= 2:
                add.add((min(b, c), max(b, c)))
    for p in add:
        keep.setdefault(p, 0.5)
    return sorted(keep)


def main():
    src = find_input()
    names, paths = list_images(src)
    n = len(names)
    log(f"{n} images from {src}, {THREADS} threads")
    feats = all_features(paths)
    log("features done")
    cand = bow_candidates(feats)
    # neighbours in name order are always checked as well (cheap)
    for i in range(n):
        for j in (i + 1, i + 2):
            if j < n:
                cand.add((i, j))
    pairs = sorted(cand)
    log(f"{len(pairs)} candidate pairs")
    X = verify_all(feats, pairs)
    log("verification done")
    prob = predict_proba(X)
    keep = decide(pairs, prob, n)
    with open("output.csv", "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["image_a", "image_b"])
        for a, b in keep:
            if names[a] != names[b]:
                w.writerow([names[a], names[b]])
    log(f"wrote {len(keep)} pairs to output.csv")


